const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
const fails = []
const all = []
page.on('response', r => {
  const u = r.url()
  if (u.includes('/wechatapph5') || u.includes('/static') || u.includes('/assets')) {
    all.push(`${r.status()} ${u}`)
    if (r.status() >= 400) fails.push(`${r.status()} ${u}`)
  }
})
page.on('requestfailed', r => fails.push(`FAILED ${r.url()} :: ${r.failure()?.errorText}`))
try {
  await page.goto(base, { waitUntil: 'networkidle', timeout: 30000 })
} catch (e) { console.log('goto error', e.message) }
